-- Operational Sense Step 4.2: import taxonomy and failure-mode vocabulary.
-- Source: Operational_Sense_Industrial_Knowledge_Base_g1.xlsx
-- Taxonomy codes are the project-local code before the pipe; ISO FM annotations
-- are retained only in source workbook text, not treated as approved mappings.
-- All taxonomy records remain PENDING_REVIEW. Vocabulary review statuses from
-- the workbook (pending_domain_review) are preserved.
-- Safe to rerun: existing primary-key records are left unchanged.

BEGIN;

INSERT INTO public.failure_mode_taxonomy
    (taxonomy_code, equipment_class_id, subsystem_id, component_name,
     failure_mode_name, description, failure_effect, failure_cause,
     corrective_action, review_status)
SELECT
    v.taxonomy_code,
    v.equipment_class_id,
    s.subsystem_id,
    v.component_name,
    v.failure_mode_name,
    v.description,
    v.failure_effect,
    v.failure_cause,
    v.corrective_action,
    v.review_status
FROM (VALUES
    ('PUMP.BRNG.ROLL', 'EQ-PUMP', 'Bearing Assembly', 'Rolling Element Bearing', 'Bearing Wear', 'Progressive spalling and pitting of raceways and rolling elements under cyclic contact stress, increasing internal clearance and friction.', 'Local: rising vibration, noise and bearing temperature. Plant: shaft deflection damages seal, risk of seizure and unplanned pump trip.', 'Contaminated or degraded grease; over/under-lubrication; misalignment; moisture ingress; bearing operated beyond rated life.', 'Replace bearings as a set; inspect shaft journals and housing fits; regrease with specified grade and quantity; re-align coupling; trend vibration after restart.', 'PENDING_REVIEW'),
    ('PUMP.SEAL.FACE', 'EQ-PUMP', 'Mechanical Seal', 'Seal Faces (Rotating / Stationary)', 'Seal Face Leakage', 'Loss of lapped seal-face contact through wear, thermal cracking, dry running or elastomer hardening, allowing process fluid to escape along the shaft.', 'Local: visible leakage at gland, wet baseplate. Plant: product loss, bearing contamination, safety and environmental exposure.', 'Dry running; shaft deflection or excessive vibration; abrasive solids; elastomer incompatibility; incorrect installation or flush plan.', 'Isolate and depressurise; replace seal faces and elastomers as a set; check shaft sleeve runout; verify flush/quench arrangement per seal plan.', 'PENDING_REVIEW'),
    ('PUMP.HYDR.IMPL', 'EQ-PUMP', 'Hydraulic End', 'Impeller', 'Cavitation', 'Vapour bubbles form when local pressure falls below fluid vapour pressure and collapse violently on impeller surfaces, causing pitting and pressure pulsation.', 'Local: gravel-like noise, vibration, pitted vanes. Plant: head and flow drop, shortened pump life, unstable process supply.', 'NPSH available below NPSH required plus margin; blocked suction; excessive suction lift; high fluid temperature; throttled suction valve.', 'Clear suction restriction; fully open suction valve; reduce lift or fluid temperature; verify NPSHa margin; repair or replace pitted impeller.', 'PENDING_REVIEW'),
    ('PUMP.HYDR.WEAR', 'EQ-PUMP', 'Hydraulic End', 'Impeller and Wear Rings', 'Impeller / Wear Ring Wear', 'Erosion or corrosion of vane tips and growth of wear-ring clearance, creating internal recirculation and reduced hydraulic efficiency.', 'Local: lower discharge pressure and flow at same motor current. Plant: process under-supply and higher energy per unit flow.', 'Abrasive particles in fluid; corrosion; extended run without clearance check; prolonged operation away from best efficiency point.', 'Measure wear-ring clearance against OEM limits; replace rings; replace or re-trim impeller; review fluid filtration.', 'PENDING_REVIEW'),
    ('PUMP.DRVT.CPLG', 'EQ-PUMP', 'Drive Train', 'Flexible Coupling', 'Coupling Misalignment', 'Angular or parallel offset between pump and driver shafts imposing cyclic loads on coupling elements, bearings and seals.', 'Local: 1x/2x running-speed vibration, coupling element wear, warm bearings. Plant: premature bearing and seal failures, repeat maintenance.', 'Poor alignment at installation; thermal growth; soft foot; pipe strain; worn inserts; loose foundation bolts.', 'Laser-align to tolerance with hot-alignment allowance; correct soft foot and pipe strain; replace worn coupling elements; retorque bolts.', 'PENDING_REVIEW'),
    ('PUMP.SUCT.STRN', 'EQ-PUMP', 'Suction Line', 'Suction Strainer', 'Strainer Blockage', 'Debris accumulation restricts suction flow and lowers pump inlet pressure.', 'Local: high suction vacuum, noise, onset of cavitation. Plant: flow reduction and risk of dry running.', 'Debris or scale in sump or line; no cleaning schedule; fouled tank; construction debris after outage.', 'Isolate and clean or replace strainer; flush suction line; fit differential-pressure indication across strainer.', 'PENDING_REVIEW'),
    ('PUMP.SHFT.SHAF', 'EQ-PUMP', 'Shaft Assembly', 'Pump Shaft', 'Shaft Fatigue Fracture', 'Crack initiation at stress raisers (keyway, step, sleeve end) under rotating bending, then propagation to fracture.', 'Local: sudden loss of drive, severe vibration beforehand, seal destruction. Plant: unplanned outage and long-lead repair.', 'Chronic misalignment or unbalance; operation far from best efficiency point; corrosion fatigue; poor fillet radii or fretting at sleeve.', 'Replace shaft; inspect keyways and shoulders by NDT; correct alignment and operating range; review shaft material and corrosion protection.', 'PENDING_REVIEW'),
    ('PUMP.SUCT.PRIM', 'EQ-PUMP', 'Suction and Priming', 'Suction Line Joints and Gland Seal Interface', 'Air Ingress / Loss of Prime', 'Air drawn through leaking suction joints or seal interface collects at the impeller eye, breaking the liquid column (gas binding).', 'Local: fluctuating or zero discharge pressure, noisy running. Plant: loss of delivery and dry-running damage to seal.', 'Loose or damaged flange gaskets; low sump level or vortexing; suction valve stem leakage; incomplete priming or venting.', 'Re-make suction joints; restore sump level; vent and prime per procedure; test suction line for air leaks before restart.', 'PENDING_REVIEW'),
    ('PUMP.HYDR.RECR', 'EQ-PUMP', 'Hydraulic End', 'Impeller and Casing Volute', 'Low-Flow Recirculation', 'Operation well below best efficiency flow produces flow separation and recirculation at impeller inlet and outlet, causing pressure pulsation and radial load.', 'Local: noise, vibration, elevated temperature. Plant: reduced bearing/seal life and risk of damage if throttled for long periods.', 'Excessive throttling; oversized pump; wrong operating point after process change; closed or blocked discharge.', 'Restore operation within the allowable operating region; fit minimum-flow bypass; trim impeller or use variable speed drive; check discharge valve position.', 'PENDING_REVIEW'),
    ('PUMP.BRNG.SEAL', 'EQ-PUMP', 'Bearing Assembly', 'Bearing Housing Isolators / Lip Seals', 'Bearing Housing Seal Failure', 'Worn lip seals or isolators let lubricant escape and let dust or moisture enter the bearing housing.', 'Local: oil leakage at shaft, contaminated lubricant. Plant: accelerated bearing failure and repeat lubricant top-ups.', 'Seal wear from shaft runout; damaged shaft surface; overfilled oil level; blocked breather causing pressure build-up.', 'Replace isolators or lip seals; inspect shaft surface; correct oil level; clean breather; change contaminated lubricant.', 'PENDING_REVIEW'),
    ('ELEC.MOT.STAT', 'EQ-MOTOR', 'Stator & Windings', 'Winding Insulation (Copper Magnet Wire and Varnish)', 'Insulation Breakdown', 'Thermal, electrical or contamination-driven degradation of winding insulation leading to turn-to-turn, phase-to-phase or ground faults.', 'Local: low insulation resistance, burning smell, current imbalance. Plant: earth-fault or overcurrent trip and process stoppage.', 'Overvoltage or voltage spikes (including inverter dv/dt); chronic overheating; moisture and dust ingress; repeated starts.', 'Test insulation resistance and polarisation index; rewind or replace motor; remove moisture source; review protection and starting duty.', 'PENDING_REVIEW'),
    ('ELEC.MOT.BRNG', 'EQ-MOTOR', 'Bearing Assembly', 'Drive-End Bearing and Grease', 'Bearing Overheating (Lubrication Failure)', 'Loss of effective lubricant film from degraded, insufficient or excess grease causes metal contact and heat rise.', 'Local: temperature rise, noise, discoloured grease. Plant: seizure, rotor-stator rub and motor trip.', 'Wrong grease type or quantity; over-greasing; lubricant beyond service life; high ambient temperature; excessive belt tension.', 'Clean and regrease with correct grade and quantity; replace damaged bearing; check belt or coupling load; revise relubrication interval.', 'PENDING_REVIEW'),
    ('ELEC.MOT.ROTR', 'EQ-MOTOR', 'Rotor Assembly', 'Squirrel-Cage Rotor Bars and End Rings', 'Broken Rotor Bar', 'Cracking or fracture of rotor bars or end rings from thermal and mechanical stress during starts and high-inertia loads.', 'Local: speed fluctuation, pulsating current, current-spectrum sidebands, vibration. Plant: reduced torque and trip under load.', 'Frequent direct-on-line starts; high-inertia load; casting defects; sustained overload.', 'Confirm by motor current signature analysis; repair or replace rotor; review start frequency and loading.', 'PENDING_REVIEW'),
    ('ELEC.MOT.COOL', 'EQ-MOTOR', 'Cooling System', 'Cooling Fan and Cowl', 'Cooling Airflow Blockage', 'Reduced convective cooling because of clogged fins or cowl, or a damaged fan, raising winding temperature.', 'Local: casing and winding temperature rise. Plant: thermal overload trip and accelerated insulation ageing.', 'Dust and lint build-up; damaged or loose fan; obstructed air inlet; high ambient temperature.', 'Clean fins and cowl; replace damaged fan; clear obstructions; verify ambient temperature and ventilation.', 'PENDING_REVIEW'),
    ('ELEC.MOT.TERM', 'EQ-MOTOR', 'Terminal Box', 'Terminal Lugs and Connections', 'Loose Electrical Connection', 'Loose or oxidised terminal joints add contact resistance, causing localised heating and unbalanced phase current.', 'Local: hot spots, discoloured lugs, current imbalance. Plant: overload trip and potential winding damage.', 'Vibration-loosened bolts; poor crimping; oxidation or corrosion; cable overloading.', 'De-energise and lock out; clean and retorque connections; replace damaged lugs; verify balanced phase currents.', 'PENDING_REVIEW'),
    ('ELEC.MOT.FEET', 'EQ-MOTOR', 'Mounting and Foundation', 'Motor Feet and Foundation Bolts', 'Soft Foot / Mechanical Looseness', 'Uneven or loose foot contact distorts the frame and alters bearing alignment, raising vibration.', 'Local: high 1x/2x vibration with directional differences. Plant: accelerated bearing wear and coupling damage.', 'Loose or corroded bolts; uneven baseplate; cracked grout; incorrect shimming.', 'Perform soft-foot check; shim and retorque; repair baseplate or grout; re-align to driven equipment.', 'PENDING_REVIEW'),
    ('ELEC.MOT.SUPP', 'EQ-MOTOR', 'Power Supply', 'Supply Phase Conductors, Fuses and Contactor', 'Single-Phasing (Phase Loss)', 'Loss of one supply phase leaves the motor on two phases, producing severe current imbalance and negative-sequence heating.', 'Local: humming, no start or reduced torque, high current in remaining phases. Plant: overload trip or winding burnout.', 'Blown fuse; failed contactor pole; open conductor or loose lug; upstream supply fault.', 'Isolate and trace the open phase; replace fuse/contactor contact; check winding insulation after event; verify phase-loss protection works.', 'PENDING_REVIEW'),
    ('ELEC.MOT.BRDC', 'EQ-MOTOR', 'Bearing Assembly', 'Bearing (Inverter-Fed Shaft Currents)', 'Bearing Electrical Discharge Damage (Fluting)', 'High-frequency common-mode currents from variable-speed drives discharge through the bearing, etching raceways with fluting.', 'Local: whining or growling noise, grey or fluted raceways. Plant: premature bearing failure on drive-fed motors.', 'No shaft grounding or insulated bearing; poor drive cabling and earthing; high switching frequency.', 'Fit insulated bearing or shaft-grounding ring; improve cable and earth bonding; replace bearing; review drive filtering.', 'PENDING_REVIEW'),
    ('ELEC.MOT.AGAP', 'EQ-MOTOR', 'Rotor-Stator Interface', 'Air Gap (Rotor and Stator Core)', 'Air-Gap Eccentricity / Rotor-Stator Rub', 'Uneven air gap from bearing wear, shaft bow or frame distortion creates unbalanced magnetic pull and can lead to rotor-stator contact.', 'Local: vibration at twice line frequency, noise, core damage. Plant: motor failure and extended outage.', 'Worn bearings; bent shaft; soft foot; assembly error after repair.', 'Measure air gap; replace bearings; straighten or replace shaft; correct mounting; inspect core and windings for rub damage.', 'PENDING_REVIEW'),
    ('ELEC.MOT.IMBL', 'EQ-MOTOR', 'Rotor Assembly', 'Rotor Core and Shaft', 'Rotor Imbalance', 'Uneven mass distribution about the rotor axis produces a centrifugal force at running speed.', 'Local: 1x running-speed vibration, bearing loading. Plant: reduced bearing life and coupling wear.', 'Lost balance weights; fan damage; uneven dirt build-up; poor balance after repair.', 'Balance rotor in situ or in shop to specified grade; clean rotor and fan; replace damaged parts; verify vibration after restart.', 'PENDING_REVIEW'),
    ('COMP.AEND.ROTR', 'EQ-COMP', 'Air End', 'Rotor Screws (Male / Female)', 'Rotor Wear / Clearance Increase', 'Gradual loss of rotor profile and sealing clearance from contamination or oil-film breakdown, increasing internal leakage.', 'Local: lower free-air delivery, higher discharge temperature and specific energy. Plant: loss of pressure and capacity.', 'Dirty intake air; degraded or wrong oil; low oil level; extended service interval; bearing wear allowing rotor contact.', 'Check oil quality and filtration; measure free-air delivery; overhaul or replace air end; correct oil and filter intervals.', 'PENDING_REVIEW'),
    ('COMP.OSEP.ELEM', 'EQ-COMP', 'Oil Separation System', 'Oil Separator Element', 'Separator Element Clogging', 'Coalescing media loads with contaminants, raising differential pressure across the element.', 'Local: high separator differential pressure and motor current. Plant: lower efficiency and oil carry-over if element fails.', 'Service interval exceeded; varnished or degraded oil; poor intake filtration; high oil temperature.', 'Replace separator element and oil filter; change oil if varnished; verify scavenge line and orifice are clear.', 'PENDING_REVIEW'),
    ('COMP.INTK.FILT', 'EQ-COMP', 'Air Intake', 'Intake Air Filter', 'Clogged Air Filter', 'Dust loading of filter media restricts intake flow and raises intake vacuum.', 'Local: reduced inlet pressure, lower capacity, higher temperature. Plant: loss of delivered air flow and pressure.', 'Dusty environment; overdue replacement; damaged filter seal allowing bypass.', 'Replace filter element; inspect housing seals; shorten replacement interval in dusty areas.', 'PENDING_REVIEW'),
    ('COMP.COOL.COLR', 'EQ-COMP', 'Cooling System', 'Oil Cooler / Aftercooler', 'Cooler Fouling', 'Fouled fins or tubes and poor ventilation reduce heat rejection from oil and compressed air.', 'Local: high discharge air and oil temperature. Plant: high-temperature trip and accelerated oil degradation.', 'Dirt on cooler core; blocked ventilation; high ambient temperature; failed cooling fan; low oil level.', 'Clean cooler externally and internally; restore ventilation; check cooling fan; verify oil level and thermostatic valve.', 'PENDING_REVIEW'),
    ('COMP.VALV.UNL', 'EQ-COMP', 'Capacity Control', 'Inlet / Unloader Valve', 'Unloader Valve Sticking', 'Inlet valve piston or seal sticks or leaks, so capacity control cannot load or unload the compressor correctly.', 'Local: compressor stays loaded at set pressure or fails to build pressure. Plant: pressure swings, wasted energy, relief valve lifting.', 'Worn seals or piston; dirt or varnish in valve; faults in control-air line.', 'Strip and clean valve; replace seal kit; check control-air tubing; verify load and unload setpoints.', 'PENDING_REVIEW'),
    ('COMP.VALV.MPV', 'EQ-COMP', 'Air-Oil Circuit', 'Minimum Pressure Valve', 'Minimum Pressure Valve Leakage / Sticking', 'Valve fails to seal or open at set pressure, causing backflow or poor pressure retention in the separator vessel.', 'Local: slow pressure build-up, oil carry-over, irregular blowdown. Plant: reduced delivery and unstable operation.', 'Worn seat or spring; varnish deposits; debris in valve.', 'Clean or replace valve kit; verify opening pressure; check oil quality and separator condition.', 'PENDING_REVIEW'),
    ('COMP.AEND.BRNG', 'EQ-COMP', 'Air End', 'Air End Bearings', 'Air End Bearing Failure', 'Rotor shaft bearings wear or spall from contaminated oil, overload or oil starvation, letting rotors move axially or radially.', 'Local: noise, vibration, rising discharge temperature. Plant: rotor contact, air end seizure, major overhaul.', 'Contaminated or degraded oil; blocked oil filter; low oil flow; overpressure operation; long service interval.', 'Replace bearings and set rotor clearances (or exchange air end); change oil and filter; investigate oil supply and filtration.', 'PENDING_REVIEW'),
    ('COMP.OILS.THRM', 'EQ-COMP', 'Oil System', 'Thermostatic (Temperature Control) Valve', 'Thermostatic Valve Sticking', 'Thermostatic element sticks open or closed, so oil is over-cooled or not routed through the cooler.', 'Local: high discharge temperature if stuck closed to cooler; condensation in oil if stuck open. Plant: high-temperature trip or oil degradation.', 'Wax element ageing; deposits or varnish; contaminated oil.', 'Test and replace thermostatic element; clean valve body; change oil if contaminated.', 'PENDING_REVIEW'),
    ('COMP.VALV.SOL', 'EQ-COMP', 'Capacity Control', 'Solenoid Valve (Load / Unload)', 'Solenoid Valve Failure', 'Coil burnout or sticking plunger prevents the control-air signal from switching the inlet valve.', 'Local: compressor stays loaded or unloaded, frequent cycling or low pressure. Plant: unstable air supply and wasted energy.', 'Coil failure; contaminated control air; worn plunger or seal; wiring fault.', 'Check coil voltage and resistance; clean or replace valve; verify control-air quality; test load/unload sequence.', 'PENDING_REVIEW'),
    ('COMP.COND.DRN', 'EQ-COMP', 'Condensate Management', 'Automatic Condensate Drain', 'Condensate Drain Blockage', 'Drain valve or strainer blocked, so condensate cannot leave the separator or receiver.', 'Local: water accumulation in receiver and lines. Plant: moisture in downstream air, corrosion and tool or process contamination.', 'Debris or rust in drain; failed solenoid or float; no routine drain check.', 'Clean or replace drain valve and strainer; test drain function; add routine drain checks.', 'PENDING_REVIEW')
) AS v(taxonomy_code, equipment_class_id, subsystem_name, component_name,
       failure_mode_name, description, failure_effect, failure_cause,
       corrective_action, review_status)
JOIN public.subsystem s ON s.subsystem_name = v.subsystem_name
ON CONFLICT (taxonomy_code) DO NOTHING;

