    ('FM-029', 'Low compressed-air pressure', 'EQ-COMP', 'Project-local ID and label from a synthetic pilot scenario; not an ISO 14224 code. Mechanism not inferred.', 'PENDING_REVIEW'),
    ('FM-030', 'Low discharge pressure', 'EQ-PUMP', 'Project-local ID and label from a synthetic pilot scenario; not an ISO 14224 code. Mechanism not inferred.', 'PENDING_REVIEW'),
    ('FM-032', 'Mechanical seal leakage', 'EQ-PUMP', 'Project-local ID and label from a synthetic pilot scenario; not an ISO 14224 code. Mechanism not inferred.', 'PENDING_REVIEW'),
