    ('FM-037', 'Motor fails to start', 'EQ-MOTOR', 'Project-local ID and label from a synthetic pilot scenario; not an ISO 14224 code. Mechanism not inferred.', 'PENDING_REVIEW'),
    ('FM-038', 'Motor hums but does not rotate', 'EQ-MOTOR', 'Project-local ID and label from a synthetic pilot scenario; not an ISO 14224 code. Mechanism not inferred.', 'PENDING_REVIEW'),
    ('FM-039', 'Motor overheating', 'EQ-MOTOR', 'Project-local ID and label from a synthetic pilot scenario; not an ISO 14224 code. Mechanism not inferred.', 'PENDING_REVIEW'),
    ('FM-040', 'Motor phase current imbalance', 'EQ-MOTOR', 'Project-local ID and label from a synthetic pilot scenario; not an ISO 14224 code. Mechanism not inferred.', 'PENDING_REVIEW'),
    ('FM-041', 'Motor speed fluctuation', 'EQ-MOTOR', 'Project-local ID and label from a synthetic pilot scenario; not an ISO 14224 code. Mechanism not inferred.', 'PENDING_REVIEW'),
