-- Counts for verification
SELECT 'failure_mode_taxonomy' AS table_name, COUNT(*) AS rows
FROM public.failure_mode_taxonomy
UNION ALL
SELECT 'failure_mode_vocabulary', COUNT(*)
FROM public.failure_mode_vocabulary
ORDER BY table_name;

COMMIT;
